<?php
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM users WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=db()->query('SELECT u.*,r.name role_name,t.full_name therapist_name FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN therapists t ON t.id=u.therapist_id ORDER BY u.created_at DESC')->fetchAll();$therapists=db()->query("SELECT id,full_name FROM therapists WHERE status='active' ORDER BY full_name")->fetchAll();
?>
<div class="page-heading"><div><div class="eyebrow">Access & permissions</div><h1>User accounts</h1><p>Create staff logins and assign administrator, receptionist, or therapist roles.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#userModal"><i class="bi bi-person-plus me-1"></i>Add user</button></div>
<div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Therapist profile</th><th>Last login</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-semibold"><?=h($r['name'])?></td><td><?=h($r['email'])?></td><td><?=h($r['role_name'])?></td><td><?=h($r['therapist_name']??'—')?></td><td><?=date_label($r['last_login_at'],'M j, Y g:i A')?></td><td><?=status_badge($r['status'])?></td><td class="text-end"><a class="btn btn-sm btn-light" href="<?=h(app_page_url('users',['edit'=>$r['id']]))?>"><i class="bi bi-pencil"></i></a></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="modal fade" id="userModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><?=post_form_start('save_user',app_page_url('users'))?><div class="modal-header"><h5 class="modal-title"><?=$edit?'Edit user account':'Create user account'?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="mb-3"><label class="form-label">Full name *</label><input class="form-control" name="name" required value="<?=h($edit['name']??'')?>"></div><div class="mb-3"><label class="form-label">Email address *</label><input class="form-control" type="email" name="email" required value="<?=h($edit['email']??'')?>"></div><div class="row g-3"><div class="col-6"><label class="form-label">Role</label><select class="form-select" name="role_id" id="roleSelect"><option value="1" <?=selected($edit['role_id']??1,1)?>>Administrator</option><option value="2" <?=selected($edit['role_id']??'',2)?>>Staff / Receptionist</option><option value="3" <?=selected($edit['role_id']??'',3)?>>Therapist</option></select></div><div class="col-6"><label class="form-label">Account status</label><select class="form-select" name="status"><option value="active" <?=selected($edit['status']??'active','active')?>>Active</option><option value="inactive" <?=selected($edit['status']??'','inactive')?>>Inactive</option></select></div><div class="col-12"><label class="form-label">Linked therapist profile</label><select class="form-select" name="therapist_id"><option value="">None</option><?php foreach($therapists as $t):?><option value="<?=$t['id']?>" <?=selected($edit['therapist_id']??'', $t['id'])?>><?=h($t['full_name'])?></option><?php endforeach;?></select><div class="form-text">Required for a Therapist login.</div></div><div class="col-12"><label class="form-label"><?=$edit?'New password (optional)':'Initial password *'?></label><input class="form-control" type="password" name="password" minlength="12" <?=$edit?'':'required'?> autocomplete="new-password"><div class="form-text">At least 12 characters. Passwords are stored using PHP password hashing.</div></div></div></div><div class="modal-footer"><a href="<?=h(app_page_url('users'))?>" class="btn btn-light">Cancel</a><button class="btn btn-primary">Save account</button></form></div></div></div></div><?php if($edit):?><script>document.addEventListener('DOMContentLoaded',()=>new bootstrap.Modal(document.getElementById('userModal')).show());</script><?php endif;?>
